public static void analyzeTrucks(Truck[] trucks) {
    if (trucks.length == 0) return;
    Truck highest = trucks[0];
    int excellent = 0, good = 0, average = 0, poor = 0;
    double totalMileage = 0;

    for (Truck t : trucks) {
        double m = t.getDistance() / t.getFuel();
        totalMileage += m;
        if (m >= 18) excellent++;
        else if (m >= 15) good++;
        else if (m >= 10) average++;
        else poor++;

        if (m > (highest.getDistance() / highest.getFuel())) {
            highest = t;
        }
    }
    System.out.println("Highest Mileage Truck: ID: " + highest.getTruckId() + ", Driver: " + highest.getDriverName());
    System.out.println("Counts -> Excellent: " + excellent + ", Good: " + good + ", Average: " + average + ", Poor: " + poor);
}
```
