public class Passenger {
    private String passengerID;
    private String airlineName;
    private double baggageWeight;
    private static double freeBaggageAllowance;

    static {
        freeBaggageAllowance = 20.0;
    }

    public Passenger(String id, String airline, double weight) {
        this.passengerID = id;
        this.airlineName = airline;
        this.baggageWeight = weight;
    }

    public double calculateExcessCharge() {
        if (baggageWeight > freeBaggageAllowance) {
            return (baggageWeight - freeBaggageAllowance) * 500;
        }
        return 0;
    }

    public static void setFreeAllowance(double allowance) {
        freeBaggageAllowance = allowance;
    }

    public String getPassengerID() {
        return passengerID;
    }

    public String getAirlineName() {
        return airlineName;
    }

    public double getBaggageWeight() {
        return baggageWeight;
    }
}
```

