import java.util.Scanner;

public class CarbonFootprint {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);

        System.out.print("Enter miles driven: ");
        double miles = scanner.nextDouble();

        System.out.print("Enter electricity consumed (kWh): ");
        double kWh = scanner.nextDouble();

        System.out.print("Enter waste generated (kg): ");
        double waste = scanner.nextDouble();

        System.out.print("Recycled? (1 for yes, 0 for no): ");
        int recycled = scanner.nextInt();

        System.out.print("Used public transport? (1 for yes, 0 for no): ");
        int publicTransport = scanner.nextInt();

        double vehicleEmission = miles * 0.40;
        double electricityEmission = kWh * 0.85;
        double wasteEmission = waste * 1.20;
        double totalFootprint = vehicleEmission + electricityEmission + wasteEmission;

        boolean isEcoFriendly = (totalFootprint < 20) && (recycled == 1) && (publicTransport == 1);

        System.out.println("Vehicle Emission: " + vehicleEmission + " kg CO2");
        System.out.println("Electricity Emission: " + electricityEmission + " kg CO2");
        System.out.println("Waste Emission: " + wasteEmission + " kg CO2");
        System.out.println("Total Footprint: " + totalFootprint + " kg CO2");
        System.out.println("Footprint < 20 achieved: " + (totalFootprint < 20));
        System.out.println("Eco-Friendly: " + isEcoFriendly);

        scanner.close();
    }
}
```

