public static void main(String[] args) {
    Truck[] trucks = {
        new Truck("T1", "Alice", 900, 40),
        new Truck("T2", "Bob", 600, 50),
        new Truck("T3", "Charlie", 800, 45)
    };

    Truck bestTruck = trucks[0];
    double maxMileage = bestTruck.calculateMileage();
    double totalMileage = 0;
    int excellent = 0, good = 0, average = 0, poor = 0;

    for (Truck t : trucks) {
        double m = t.calculateMileage();
        totalMileage += m;
        if (m > maxMileage) {
            maxMileage = m;
            bestTruck = t;
        }
        if (m >= 18) excellent++;
        else if (m >= 15) good++;
        else if (m >= 10) average++;
