public class CarbonFootprint {
    public static void main(String[] args) {
        double miles = 10.0;
        double kwh = 5.0;
        double waste = 2.0;
        int recycled = 1;
        int publicTransport = 1;

        double vehicleEmission = miles * 0.40;
        double electricityEmission = kwh * 0.85;
        double wasteEmission = waste * 1.20;
        double total = vehicleEmission + electricityEmission + wasteEmission;

        boolean lessThan20 = total < 20;
        boolean isEcoFriendly = lessThan20 && (recycled == 1) && (publicTransport == 1);

        System.out.println("Vehicle: " + vehicleEmission);
        System.out.println("Electricity: " + electricityEmission);
        System.out.println("Waste: " + wasteEmission);
        System.out.println("Total: " + total);
        System.out.println("Under 20: " + lessThan20);
        System.out.println("Eco-Friendly: " + isEcoFriendly);
    }
}
```

